-- # Lernfeld 5: Cyberphysische Systeme > ## Projektmanagement > - Umfeld analysieren

INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Ja/Nein-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Kann eine Projektplanung ohne Analyse des Umfelds zuverlässige Ergebnisse liefern?', 2, '[{"text": "Nein", "correct": true, "because": "Umfeld beeinflusst Risiken und Ressourcen"}, {"text": "Ja", "correct": false, "because": "Ohne Analyse fehlt Kontext"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist die Umfeldanalyse nur zu Projektbeginn relevant?', 2, '[{"text": "Nein", "correct": true, "because": "Änderungen erfordern fortlaufende Analyse"}, {"text": "Ja", "correct": false, "because": "Dynamik muss überwacht werden"}]'),
('00000000-0000-0000-0000-000000000000', 'Können externe Faktoren wie Gesetzesänderungen ein Projekt ohne vorherige Umfeldanalyse zum Scheitern bringen?', 2, '[{"text": "Ja", "correct": true, "because": "Unbekannte Faktoren sind Risiken"}, {"text": "Nein", "correct": false, "because": "Analyse mindert solche Risiken"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist eine SWOT-Analyse ausreichend, um das gesamte Projektumfeld vollständig zu verstehen?', 2, '[{"text": "Nein", "correct": true, "because": "SWOT ist nur ein Teil der Analyse"}, {"text": "Ja", "correct": false, "because": "Weitere Methoden nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann die Umfeldanalyse interne Ressourcen ignorieren, wenn der Fokus auf externen Stakeholdern liegt?', 2, '[{"text": "Nein", "correct": true, "because": "Interne Faktoren sind ebenso entscheidend"}, {"text": "Ja", "correct": false, "because": "Ganzheitliche Analyse erforderlich"}]'),

-- Single-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Methode wird primär genutzt, um Stärken und Schwächen im Projektumfeld zu identifizieren?', 2, '[{"text": "SWOT-Analyse", "correct": true, "because": "Fokussiert auf intern und extern"}, {"text": "PERT-Analyse", "correct": false, "because": "Zeitplanung"}, {"text": "Gantt-Diagramm", "correct": false, "because": "Projektablauf"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Faktor des Projektumfelds beeinflusst die Ressourcenverfügbarkeit am stärksten?', 3, '[{"text": "Organisatorische Struktur", "correct": true, "because": "Bestimmt Zugriff auf Mittel"}, {"text": "Technologische Trends", "correct": false, "because": "Indirekter Einfluss"}, {"text": "Marktbedingungen", "correct": false, "because": "Externer Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Werkzeug hilft, die Einflüsse von Stakeholdern im Umfeld zu bewerten?', 2, '[{"text": "Stakeholder-Matrix", "correct": true, "because": "Kategorisiert Einfluss und Interesse"}, {"text": "Risikoregister", "correct": false, "because": "Fokus auf Risiken"}, {"text": "Meilensteinplan", "correct": false, "because": "Zeitlich orientiert"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche externe Kraft kann ein Projektumfeld unerwartet verändern?', 2, '[{"text": "Politische Veränderungen", "correct": true, "because": "Gesetze und Regularien wirken direkt"}, {"text": "Teamdynamik", "correct": false, "because": "Interner Faktor"}, {"text": "Projektbudget", "correct": false, "because": "Intern kontrollierbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist das Hauptziel der Umfeldanalyse in der Projektinitiierung?', 2, '[{"text": "Risiken und Chancen identifizieren", "correct": true, "because": "Grundlage für Planung"}, {"text": "Budget festlegen", "correct": false, "because": "Folge der Analyse"}, {"text": "Team zusammenstellen", "correct": false, "because": "Spätere Phase"}]'),

-- Multiple-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Elemente gehören zur Analyse des Projektumfelds?', 4, '[{"text": "Interne Ressourcen", "correct": true, "because": "Verfügbarkeit ist entscheidend"}, {"text": "Externe Stakeholder", "correct": true, "because": "Beeinflussen Projekt"}, {"text": "Technische Machbarkeit", "correct": true, "because": "Grenzen der Umsetzung"}, {"text": "Tägliche Arbeitszeiten", "correct": false, "because": "Operative Details"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Methoden unterstützen die Umfeldanalyse effektiv?', 3, '[{"text": "PESTLE-Analyse", "correct": true, "because": "Externe Faktoren abdecken"}, {"text": "SWOT-Analyse", "correct": true, "because": "Stärken und Schwächen"}, {"text": "Gantt-Diagramm", "correct": false, "because": "Zeitmanagement"}, {"text": "Stakeholder-Analyse", "correct": true, "because": "Einflüsse bewerten"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche externen Faktoren können das Projektumfeld beeinflussen?', 3, '[{"text": "Wirtschaftliche Lage", "correct": true, "because": "Ressourcen und Kosten"}, {"text": "Rechtliche Vorgaben", "correct": true, "because": "Regularien einschränkend"}, {"text": "Teamgröße", "correct": false, "because": "Interner Faktor"}, {"text": "Technologische Entwicklungen", "correct": true, "because": "Neue Möglichkeiten"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Risiken ergeben sich aus einer unzureichenden Umfeldanalyse?', 4, '[{"text": "Unvorhergesehene Kosten", "correct": true, "because": "Fehlende Faktoren teuer"}, {"text": "Verzögerungen durch Stakeholder", "correct": true, "because": "Einflüsse unterschätzt"}, {"text": "Perfekte Planung", "correct": false, "because": "Widerspricht Mängeln"}, {"text": "Unbekannte rechtliche Hürden", "correct": true, "because": "Gesetze übersehen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche internen Aspekte sollten in der Umfeldanalyse berücksichtigt werden?', 3, '[{"text": "Unternehmenskultur", "correct": true, "because": "Beeinflusst Zusammenarbeit"}, {"text": "Verfügbare Kompetenzen", "correct": true, "because": "Bestimmt Umsetzung"}, {"text": "Wetterbedingungen", "correct": false, "because": "Externer Faktor"}, {"text": "Organisationsstruktur", "correct": true, "because": "Ressourcenverteilung"}]'),

-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Die Umfeldanalyse ist nur für große Projekte notwendig. b) Externe Faktoren können die Projektdauer verlängern.', 3, '[{"text": "Nur b) stimmt", "correct": true, "because": "Analyse immer nötig, externe Faktoren wirken"}, {"text": "Beides stimmt", "Sind folgende Aussagen richtig? "correct": false, "because": "a) ist falsch"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "b) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Eine PESTLE-Analyse deckt interne Schwächen ab. b) Stakeholder können das Projektumfeld entscheidend beeinflussen.', 3, '[{"text": "Nur b) stimmt", "correct": true, "because": "PESTLE extern, Stakeholder einflussreich"}, {"text": "Beides stimmt", "correct": false, "because": "a) ist falsch"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "b) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Die Umfeldanalyse kann Risiken vollständig eliminieren. b) Interne Ressourcen sind Teil des Projektumfelds.', 3, '[{"text": "Nur b) stimmt", "correct": true, "because": "Risiken bleiben, Ressourcen relevant"}, {"text": "Beides stimmt", "correct": false, "because": "a) ist falsch"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "b) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) Eine unvollständige Umfeldanalyse erhöht Projektkosten. b) Technologische Trends sind für jedes Projekt irrelevant.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Kosten steigen, Trends oft relevant"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Die Umfeldanalyse ist eine einmalige Aufgabe. b) Eine SWOT-Analyse berücksichtigt externe Chancen.', 3, '[{"text": "Nur b) stimmt", "correct": true, "because": "Analyse fortlaufend, SWOT umfassend"}, {"text": "Beides stimmt", "correct": false, "because": "a) ist falsch"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "b) ist richtig"}]');

